        # If the wealth is greater than 10,000M, it's guaranteed they can avoid being thrown off the roof.
        return M > 10000

    def optimal_plan(proposal):
        # B/W Boolean -> The number of negative numbers in the proposal
        proposal = sorted(proposal, reverse=True)
        balance = 0
        for bill in proposed_plan:
            if balance >= 0:
                balance += bill
            else:
                break
        return sum(proposal[x-1] - bill for x, bill in enumerate(proposed_plan) if proposal[x-1] > proposed_plan.count(-balance))

    H = [0]
    N = M = 0
    plan_accepted = False
    proposals = []
    reserved_balance = 0
    accepted_plans = set()
    for _ in range(Q):
