        proposals.append([can_avoid_thrown_off(x, M) for x in range(min(K, N))])
        if N <= K * 4:
            H2 = [1]
            for bill in range(M):
                sums = [b for b in H2]
                new_sum = H2[max(0, len(H2) - 2)] - sums[0] - H2[-1]
                sums.append(min(K - 1, H2.index(max(H2)) + 1))
                if new_sum - sums[0] - sums[-1] > 0:
