def max_happiness(items, p, visits, budgets):
    max_happiness = 0
    for visit in visits:
        time, budget = visit
        current_time = 0
        available_items = []
        max_happiness_this_visit = 0

        for item in items:
            cost, happiness, start_time = item
            if current_time < start_time + (p - 1):
                available_items.append(item)
            elif start_time + (p - 1) <= time:
                if cost <= budget:
                    max_happiness_this_visit += happiness
                    current_time = max(start_time + p, time)
                    if start_time + p in budgets:
                        budget -= cost
                        if budget >= 0:
                            max_happiness_this_visit += min(3000, sum(budgeting for _, budgeting in items if budgeting >= budget) - budget)
                else:
                    break
            elif current_time >= time:
                break

