from collections import defaultdict

def count_occurrences(s, t, k):
    n = len(t)
    t_count = defaultdict(int)
    occurrences = 0
    left = -n + 1

    for i in range(len(s) - n + 1):
        t_sub = s[i:i+n]
        if n - i > left:
            occurrences -= count_matches(t_sub)
        t_count[t_sub] += 1

        if left and (i + left) < len(s) and s[i + left] == s[i + n - (left + 1)]:
            occurrences += 1
        else:
            left = max(0, left - 1)

    i = occurrences + n
    i += k + 1  # Adding 1 to cover the frequency count in the first loop

    for k in reversed(range(i)):
        l = k - n + 1
        if l < 0:
            break
        t_count[t[0:-(l + 1)]] -= 1
        if l < 0 or (k - l > left):
            occurrences -= count_matches(t[0:-(l + 1)])
        else:
            occurrences -= count_matches(t[0:-(l + 1)] + t[l + 1:(i + 1)])

    return occurrences

def count_matches(t):
    occurrences = 0
    for match in matching_pairs(t):
        occurrences += t_count[match]

    return occurrences

def matching_pairs(seq):
    for i in range(1, len(seq)):
        if seq[0] == seq[i]:
            yield seq[0: (i + 1) // 2]

    if len(seq) % 2 == 1:
        yield seq[-1]

    left, left2 = left_end, left_end2 = 0, 0
    target, n = len(seq), 0
    i, j = 0, 0

    while target < n and not (i == j and left == left2):
        if seq[i] == seq[j]:
            while left < n and seq[left] == seq[i + left]:
                left += 1
            while left2 < n and seq[left2] == seq[j] and (left - left2) <= k:
                left2 += 1

            if left == left2:
                i += left
                left = 0
            else:
                # left < left2 and i < j; now i is after j with an overlap (or left matches)
                i += max(0, left2 - 1)
                left = (i - j + 1) // 2
                left2 = min(i, (j - (i - left) + k) // 2)
        j += 1
    if left:
        yield seq[0: (left + 1) // 2]

    return

