import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def dfs(cards, skip):
    if all(card == 1 for card in cards):
        return 'carries'
    if skip:
        i = cards.index(gcd(cards[0], skip))
        cards[i:i+2] = cards[i] // gcd(cards[0], skip), cards[i+1] // gcd(cards[0], skip)
        cards.pop()
        return dfs(cards, 0)
    else:
        cards.append(gcd(cards[0], skip))
        cards.pop(0)
        skip = False
        return cards

def optimal_probability(cards):
    return 1 if not cards else 0.5

def random_probability(cards):
    cards_count = [cards.count(card) for card in set(cards)]
    if sum(cards_count) > cards_count[1]:
        return (1 - max(cards_count)) / (max(cards_count) - 1)
    elif max(cards_count) == 0:
        return 1
    else:
        return cards_count[1] / max(cards_count)

