def count_occurrences(s, t, k):
    from collections import defaultdict

    # Initialize a map to keep track of the positions where substrings starting at each position match a starting position of T within a distance of k
    positions = defaultdict(int)

    for i in range(len(t) + 1):
        # Compare the substring s[i:i+len(t)] with t
        for j in range(i, len(s) - len(t) + 1):
            if s[j:j+len(t)] == t:
                if k == 0:
                    positions[j + 1] += 1
                else:
                    # Check if the substring S within distance k matches the substring T
                    for d in range(max(0, j + 1 - k), min(len(s) - 1, j + len(t) + 1 + k)):
                        if abs((s[d]) - (t[j])) <= k:
                            positions[j + 1] += 1

    return len(positions)

