def count_pairs(A):
    MOD = 10**9 + 7
    dp = [1] * (len(A) + 1)  # dp[i] will store the number of ways to form pairs up to index i

    for i in range(1, len(A)):
        for j in range(i):
            if A[i] % A[j] == 0:  # Check if A[i] is divisible by A[j]
