from collections import defaultdict

def count_universes(planets):
    planet_graph = defaultdict(list)

    # Build the adjacency list to represent the graph structure
    for i, (x, y) in enumerate(planets):
        planet_graph[(x, y)].append((i, 0))
        planet_graph[(x, y)].append((i, 1))

    # DFS to calculate the connected components
    def dfs(i, visited, stack):
        visited.add(i)
        stack.append(i)
        for neighbor in planet_graph[i]:
            if neighbor[0] not in visited:
                dfs(neighbor[0], visited, stack)
        return stack[1:]

    connected_components = {}
    for point in planet_graph:
        if point[0] * point[1] < 0:
            continue  # Skip planets on the axis
        if len(dfs(point, set(), [])) > 2:
            if point in connected_components:
                continue
            connections = 0
            for i in range(len(dfs(point, set(), []))):
                if i % 2 == 0:
                    pass
                else:
                    connections += 2  # Both are on the same side of a row or column
            connected_components[point] = {"points": len(dfs(point, set(), [])), "connections": connections}

    # If each connected component is an universe, the answer is equal to n
    if len(connected_components) == len(planets):
        answer = len(planets)
    else:
        # Calculate the number of universes by multiplying the connected components
        answer = 1
        for k, v in connected_components.items():
            answer *= v["connections"]

    return answer


