from collections import defaultdict, deque

def bfs(g, start, visited):
    queue = deque([start])
    level = {start: 0}
    while queue:
        node = queue.popleft()
        for neighbor in g[node]:
            if neighbor not in level:
                queue.append(neighbor)
                level[neighbor] = level[node] + 1
    return level

def find_cycle_and_levels(g, start):
    level = bfs(g, start, set())
    used = set()
    for neighbor in g[start]:
        if neighbor not in used:
            Cyclesused = set()
            for j in range(1, level[neighbor] // 2):
                backup = set()
                used.add(neighbor)
                temppath = [neighbor]
                q = deque([neighbor])
                while q:
                    current = q.pop()
                    for candidate in g[current]:
                        if candidate not in temppath:
                            if candidate not in used:
                                q.appendleft(candidate)
                                temppath.appendleft(candidate)
                            elif candidate in backup:
                                raise Exception("Oops, that's not possible")
                            else:
                                used.remove(candidate)
                        else:
                            Cyclesused.add(candidate)
                # If the DFS hasn't returned, there was no cycle
                if Cyclesused:
                    for candidate in Cyclesused:
                        used.remove(candidate)
            used.remove(start)
            start = start if start not in used else start^candidate
    return level

def solve(n, m, q):
    g = defaultdict(list)
    for i in range(1, m + 1):
        u, v = map(int, input().split())
        g[u].append(v)
        g[v].append(u)
    odd_cycles = 0
    output = []
    for day in range(1, q + 1):
        level = find_cycle_and_levels(g, day)
        qf = defaultdict(int)
        for node in level:
            int(node)
            qf[level[node]] += 1
            if level[node] % 2 == 0:
                odd_cycles += 1
        if odd_cycles % 2 == 1:
            output.append("YES")
        else:
            output.append("NO")
        qf[0] -= 1
        for prev in qf:
            qf[prev] = max(0, qf[prev] - 1)
        odd_cycles = qf[0]
    return "\n".join(output)

