            solved[j] = True

    total_solved = {i: c for i, c in enumerate(sieved)}  # Track numbers with solved sieve

    for i in range(2, 101):
        if total_solved[i] == i and i > 1: 
            for j in range(i, 101): 
                total_solved[j] = max(total_solved[j] if j in total_solved else 0, total_solved[i - j] + 1) # Update sieve values if prime and not solved

    def dfs(i):
        if total_solved[i] <= 0: return 0
        if dfs.memo[i] != -1: return dfs.memo[i]

        dfs.memo[i] = 0
        if i in total_solved:
