import sys

def verify_schedule(junctions, days):
    # Create an adjacency list to store the streets
    streets = [[] for _ in range(len(junctions))]

    # Initialize a counter to keep track of watched streets
    watched_streets_count = 0

    # Populate the adjacency list with the given streets
    for street in streets:
        head, tail = junctions[street[0]-1], junctions[street[1]-1]
        if head != tail:
            streets[head].append(tail)
            streets[tail].append(head)
        elif watched_streets_count % 2 != 0:
            watched_streets_count += 1

    # Simulate the execution of the plan on each day
    for day in range(days):
        watched_streets_count = 0
        for street in streets:
            if len(street) % 2 != 0 and watched_streets_count % 2 != 0:
                watched_streets_count += 1

    return watched_streets_count % 2 == 0

# Read the input
N, M, Q = map(int, sys.stdin.readline().split())
junctions = list(range(1, N+1))

# If Q == 1, the condition for executing the plan cannot be determined on the first day
if Q == 1:
    sys.stdout.write("NO\n")
else:
    for line in sys.stdin:
        line = line.strip()
        if line:
            l, r = map(int, line.split())
            days = set()
            for i in range(l-1, r):
                levels = sys.stdin.readline().strip().split()
                days.add((int(levels[0]), int(levels[1])))
            if any(isinstance(x, tuple) for x in days):
                no_plan = verify_schedule(junctions, days)
                if no_plan:
                    sys.stdout.write("NO\n")
                else:
                    sys.stdout.write("YES\n")
