from math import sqrt

def calculate_distances(points, ax, ay):
    distances = []
    for i in range(len(points)):
        for j in range(len(points)):
            if i != j:
                x1, y1 = points[i]
                x2, y2 = points[j]
                dist = sqrt((x2 - x1)**2 + (y2 - y1)**2)
                if dist < 1e-6:
                    continue
                if ax > x2 and ay == y1:
                    distances.append(dist)
                if ax < x2 and ay == y1:
                    distances.append(-dist)
                if ax > x1 and ay < y2:
                    distances.append(-dist)
                if ax < x1 and ay < y2:
                    distances.append(dist)
    return sorted(distances)

def find_lines(points, a, b, c, d):
    lines = []
    indices = list(zip(a, b, c, d))
    for i in range(len(indices)):
        for j in range(i + 1, len(indices)):
            x1, y1 = indices[i]
            x2, y2 = indices[j]
            if x2 >= x1:
                lines.append((x1, x2))
            else:
                lines.append((x2, x1))
            if y2 >= y1:
                lines.append((y1, y2))
            else:
                lines.append((y2, y1))
