                    while mx > 1:
                        mx //= gcd(mx,p[i])
                    for i in range(n-vis[i]):
                        while mx > 1 and vis[p[i] > mx]:
                            mx //= gcd(mx,p[i])
                        vis[p[i] > mx] = True
                    if s[p[i]] < mx:  # if the level at which the paper equals mx is at least mx
                        new_seralja = False
                if not new_seralja: break
            if not new_seralja:
                break
        return all(vis[i] for i in range(n))

    # Calculate all levels
    levels = [find_level(p[i]) for i in range(n)]

