    memo = {}
    def count_pairs(s1, e1, s2, e2):
        if (s1, e1, s2, e2) in memo:
            return memo[(s1, e1, s2, e2)]

        total_pairs = 0
        pre = 0
        for l1, r1 in lucky_occurrences[s1]:
            if l1 < s1 or r1 <= s2:
                pre += 1
                continue

            pre += len(lucky_occurrences[r1+1]) - len(lucky_occurrences[l1])

        for l2, r2 in lucky_occurrences[s2]:
            if l2 < s2 or r2 <= e1:
                continue

            total_pairs += min(r2 - r1, e2 - e1)

        memo[(s1, e1, s2, e2)] = total_pairs
        return total_pairs

    results = []
    total_pairs = 0
    for s1, e1 in lucky_occurrences.items():
        for s2, e2 in lucky_occurrences.items():
            total_pairs += count_pairs(s1, e1, s2, e2)
        total_pairs *= len(s1)
        results.append(total_pairs)

