from collections import defaultdict

def game_probability(arr):
    all_cards = defaultdict(int)
    for num in arr:
        all_cards[num] += 1
    prime_factors = defaultdict(int)

    for num, occurrences in all_cards.items():
        for factor, power in prime_factors.items():
            if gcd(factor, num) == 1:
                prime_factors[factor] += occurrences

    total_cards = sum(all_cards.values())

    def dfs(stack, prime_factors_copy):
        if not stack:
            return 1.0
        probability = 1.0 / total_cards
        seen = set()
        while stack:
            x = stack.pop()
            if int(x) in seen or len(seen) == len(stack):
                continue
            found_first_card = False
            for factor, occ_num in prime_factors_copy.items():
                if gcd(int(x), factor) == 1:
                    prime_factors_copy[factor] -= occ_num
                    if prime_factors_copy[factor] == 0:
                        del prime_factors_copy[factor]
                    probability *= 1 - dfs(stack, prime_factors_copy)
                    break
                if int(x) % factor == 0:
                    stack.append(str(x)//factor)
                    found_first_card = True
                    break
            if not found_first_card:
                seen.add(int(x))
                stack.append(str(x))
        return probability

    return (dfs([], prime_factors.copy()), dfs([], prime_factors))

