import sys

def find_connected_components(K, M, x):
    BIT_SET = [0] * (1 << K)
    for bit in x:
        BIT_SET[bit] ^= 1

    connected_components = 0
    while all(BIT_SET) == 1:
        connected_components += 1
        new_basetset = 0
        for i in range(K - 1, -1, -1):
            new_basetset = BIT_SET[i] ^ (1 << i)
            for j in range(i + 1, K):
                if BIT_SET[i] != new_basetset & BIT_SET[j]:
                    new_basetset ^= BIT_SET[j]
            if all(BIT_SET) == new_basetset:
                BIT_SET = new_basetset
                break

    return connected_components

