from math import gcd

def get_linear_combination(seq):
    linear_combinations = [x for x in zip(seq[1:], seq)]
    sequence_length = len(seq)
    odd_coefficients = [gcd(linear_combination[0], n) for linear_combination, n in zip(linear_combinations, range(1, sequence_length)) if linear_combination[1] % 2 != linear_combination[0] % 2]
    even_coefficients = [gcd(linear_combination[0], n + 1) for linear_combination, n in zip(linear_combinations, range(1, sequence_length)) if linear_combination[1] % 2 == linear_combination[0] % 2]
    return sum(odd_coefficients), sum(even_coefficients)

def compute_ultimate_weirdness(n, sequence):
    sequences = []
    for start in range(len(sequence)):
        for end in range(start + 1, len(sequence)):
            sequences.append(sequence[start:end])
    return sum(get_linear_combination(sequences), (0, 0))

