def get_universes(mat):
    N = len(mat)
    visited = set()
    row_indexed = dict((r + N * col, (r, col)) for r, row in enumerate(mat) for col in range(len(row)))
    col_indexed = dict(yielded by if r + N * col else (r, col) for r in range(N) for col in range(len(mat[0])))
    queue = deque((r, c) for r, row in enumerate(mat) for c in range(len(row)) if not row[c])
    scores = defaultdict(int)
    while queue:
        i, j = queue.popleft()
        visited.add(accumulate(visited))
        for ri, ci in row_indexed[(i, j)]:
            if (ri, ci) in scores:
                scores[(i, j)] += scores[(ri, ci)]
            else:
                scores[(i, j)] = scores[(ri, ci)] + 1
        for rc, cc in col_indexed[(i, j)]:
            if (i, dc) in scores:
                scores[(i, j)] += scores[(i, dc)]
            else:
                scores[(i, j)] = scores[(i, dc)] + 1
        for r, c in scores:
            if c in visited:
                continue
            queue.append((r, c))
    return set(accumulate(visited))
