def solve(n, m, repetitions):
    max_gain = -10**100
    lhs, rhs = 1, 1
    remainder = m % n

    for r in range(1, n + 1):
        for i in range(min(n - remainder, repetition + 1)):
            multiplier = math.factorial(n - remainder - i) * lhs
            denominator = math.factorial(i) * math.factorial(n - remainder - i - i)
            if not remainder:
                divisor = math.factorial(repetition * rhs)
            else:
                divisor = math.factorial(repetition * lhs + rhs)
            rem = (m - remainder * (repetition - 1)) % n
            if rem <= i:
                if rem == 0:
                    max_gain = max(max_gain, lhs * multiplier // divisor)
                lhs = remainder * lhs
                rhs = i * rhs

