                n_less_than = sum([1 for j in range(number_of_friends) if not caught_times[j]])
                if misha_guess_next_friend & {j for j in range(number_of_friends) if not caught_times[j]}:
                    misha_guess_next_friend - {j for j in range(number_of_friends) if not caught_times[j]}
                    caught_times[i] += 1
                    misha_guess_next_friend&{j for j in range(number_of_friends) if not caught_times[j]}
                else:
                    misha_guess_next_friend.add(i)
                catch_guess_prob = sum([1]*caught_times[j] + [1 - probabilities[j]*caught_times[j]]*(number_of_friends - caught_times[j])) / number_of_friends

        expected_rounds += guess_deadline * (1 - catch_prob)

    return expected_rounds

if __name__ == "__main__":
    number_of_friends = int(input().strip()) 
    probabilities = list(map(int, input().split(' ')))
    print(simulate_with_optimal_strategy(number_of_friends, probabilities))
