import math

def calculate_subarrays(X, A):
    N = len(A)
    count = 0
    sum_product = 1
    for i in range(N):
        if A[i] > X**2 * X:
            count += 1
            sum_product *= X
        else:
            sum_product *= A[i]
        if X == 1:
            return N
        for j in range(i + 1, N):
            if (sum_product // A[j]) ** (1/j) == X:
                count += 1
    return count

def main():
    T = int(input())
    for case in range(1, T + 1):
        N, X = map(int, input().split())
        A = list(map(int, input().split()))
        print(calculate_subarrays(X, A))

if __name__ == "__main__":
    main()
