import sys

# Read input
def parse_input():
    n = int(sys.stdin.readline().strip())
    if n == 0:
        return None
    return [tuple(map(int, line.strip().split())) for line in sys.stdin.readlines()]

# Function to convert planet coordinates to a single simplified planet
def simplify(planet1, planet2):
    x1, y1 = planet1
    x2, y2 = planet2
    if abs(x1 - x2) == 1 and abs(y1 - y2) == 1:
        return False, False
    max_x, max_y, min_x, min_y = max(x1, x2), max(y1, y2), min(x1, x2) + 1, min(y1, y2) + 1
    return max(max_x, min_x) - min(max_x, min_x), max(max_y, min_y) - min(max_y, min_y)

# Main logic
def main():
    planets = parse_input()
    if planets is None:
        return 0
    all_simplices = set()
    for i in range(len(planets) - 1):
        for j in range(i + 1, len(planets)):
            if simplified := simplify(planets[i], planets[j]):
                all_simplices.add(simplified[0])
                all_simplices.add(simplified[1])
    reduced = len(all_simplices)
    # Case 1 with (i, 0) line
    for i in range(len(planets) - 1):
        for j in range(i + 1, len(planets)):
            if planets[i][1] == 0 or planets[j][1] == 0:
                continue
            reduced += (1 if all_simplices <= {max(planets[i][0], planets[j][0]), min(planets[i][0], planets[j][0])} else 0)
    return reduced

if __name__ == "__main__":
    print(main())
